'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

let pos = 0;
const N = input[pos++];
const M = input[pos++];
const n = N * M;

const power = new Float64Array(n);
const order = new Array(n);

for (let i = 0; i < n; i++) {
  power[i] = input[pos++];
  order[i] = i;
}

order.sort((a, b) => power[a] - power[b]);

const dsuParent = new Int32Array(n);
const dsuSize = new Uint32Array(n);
const componentNode = new Int32Array(n);
const active = new Uint8Array(n);

for (let i = 0; i < n; i++) {
  dsuParent[i] = i;
  dsuSize[i] = 1;
  componentNode[i] = i;
}

const maxNodes = 2 * n;
const nodeSum = new Float64Array(maxNodes);
const nodeThreshold = new Float64Array(maxNodes);
const nodeParent = new Int32Array(maxNodes);
nodeParent.fill(-1);

for (let i = 0; i < n; i++) {
  nodeSum[i] = power[i];
  nodeThreshold[i] = power[i];
}

function find(x) {
  let root = x;
  while (dsuParent[root] !== root) root = dsuParent[root];

  while (dsuParent[x] !== x) {
    const next = dsuParent[x];
    dsuParent[x] = root;
    x = next;
  }
  return root;
}

let nodeCount = n;
const baseNode = new Int32Array(n);

function unite(a, b, threshold) {
  let ra = find(a);
  let rb = find(b);
  if (ra === rb) return;

  const nodeA = componentNode[ra];
  const nodeB = componentNode[rb];
  const mergedNode = nodeCount++;

  nodeSum[mergedNode] = nodeSum[nodeA] + nodeSum[nodeB];
  nodeThreshold[mergedNode] = threshold;
  nodeParent[nodeA] = mergedNode;
  nodeParent[nodeB] = mergedNode;

  if (dsuSize[ra] < dsuSize[rb]) {
    const temp = ra;
    ra = rb;
    rb = temp;
  }

  dsuParent[rb] = ra;
  dsuSize[ra] += dsuSize[rb];
  componentNode[ra] = mergedNode;
}

for (let start = 0; start < n;) {
  let end = start + 1;
  const threshold = power[order[start]];
  while (end < n && power[order[end]] === threshold) end++;

  for (let k = start; k < end; k++) {
    active[order[k]] = 1;
  }

  for (let k = start; k < end; k++) {
    const v = order[k];
    const col = v % M;

    if (col > 0 && active[v - 1]) unite(v, v - 1, threshold);
    if (col + 1 < M && active[v + 1]) unite(v, v + 1, threshold);
    if (v >= M && active[v - M]) unite(v, v - M, threshold);
    if (v + M < n && active[v + M]) unite(v, v + M, threshold);
  }

  for (let k = start; k < end; k++) {
    const v = order[k];
    baseNode[v] = componentNode[find(v)];
  }

  start = end;
}

const best = new Float64Array(nodeCount);

for (let i = nodeCount - 1; i >= 0; i--) {
  const parent = nodeParent[i];
  if (parent !== -1 && nodeThreshold[parent] <= nodeSum[i]) {
    best[i] = best[parent];
  } else {
    best[i] = nodeSum[i];
  }
}

const output = [];
for (let r = 0; r < N; r++) {
  const row = [];
  for (let c = 0; c < M; c++) {
    const v = r * M + c;
    row.push(String(best[baseNode[v]]));
  }
  output.push(row.join(' '));
}

process.stdout.write(output.join('\n'));
